export const levelKeys = ['starters', 'movers', 'flyers', 'ket']

export function getWordsByLevel(levelKey) {
  return cambridgeWordBank[levelKey]?.words || []
}

export function getAllWords() {
  return levelKeys.flatMap(key =>
    cambridgeWordBank[key].words.map(w => ({ ...w, level: key, levelName: cambridgeWordBank[key].level }))
  )
}

export function getWordCount() {
  return levelKeys.reduce((sum, key) => sum + cambridgeWordBank[key].words.length, 0)
}
